const fig = code.match(/<figure[\s\S]*?<\/figure>/i);
if (!fig || !/<img\s/i.test(fig[0]) || !/<figcaption[\s\S]*?<\/figcaption>/i.test(fig[0])) {
  throw new Error("The <figure> must contain both the <img> and a <figcaption>.");
}

const fig = code.match(/<figure[\s\S]*?<\/figure>/i)[0];
const img = fig.match(/<img\s[^>]*>/i)[0];
const src = img.match(/src=["']([^"']*)["']/i);
const alt = img.match(/alt=["']([^"']*)["']/i);
if (!src || src[1] !== "/images/market.jpg") throw new Error("src must be /images/market.jpg");
if (!alt || alt[1].trim() !== "A crowded farmers market on a Saturday morning") {
  throw new Error("alt must be: A crowded farmers market on a Saturday morning");
}

const fig = code.match(/<figure[\s\S]*?<\/figure>/i)[0];
const cap = fig.match(/<figcaption[^>]*>([\s\S]*?)<\/figcaption>/i);
if (!cap || cap[1].trim() !== "Saturday, 7 a.m.") {
  throw new Error("The figcaption must read exactly: Saturday, 7 a.m.");
}
